function encode(command) {
  if (Array.isArray(command)) {
    if (command.length !== 2) throw new Error("channels must contain exactly 2 values");
    var a = Number(command[0]);
    var b = Number(command[1]);
    if (!isFinite(a) || !isFinite(b)) throw new Error("channel values must be finite numbers");
    if (Math.abs(a) > 0.1 || Math.abs(b) > 0.1) throw new Error("channel value out of range [-0.1, 0.1]");
    return JSON.stringify({op: "step", channels: [a, b]}) + "\n";
  }
  if (command && typeof command === "object") {
    if (command.op === "lift") {
      if (command.position !== "up" && command.position !== "down") throw new Error("lift position must be up or down");
      return JSON.stringify({op: "lift", position: command.position}) + "\n";
    }
    if (command.op === "grip") {
      if (command.state !== "open" && command.state !== "closed") throw new Error("grip state must be open or closed");
      return JSON.stringify({op: "grip", state: command.state}) + "\n";
    }
  }
  throw new Error("unsupported command");
}

function decode(rawReply) {
  var reply = rawReply;
  if (typeof rawReply === "string") {
    var text = rawReply;
    if (text.length === 0 || text.charAt(text.length - 1) !== "\n") throw new Error("reply frame must end with LF");
    text = text.replace(/\r?\n$/, "");
    if (text.indexOf("\n") !== -1 || text.indexOf("\r") !== -1) throw new Error("reply must be exactly one line");
    try {
      reply = JSON.parse(text);
    } catch (e) {
      throw new Error("invalid JSON reply");
    }
  }
  if (!reply || typeof reply !== "object" || Array.isArray(reply)) throw new Error("reply is not an object");
  if (reply.ok !== true) {
    throw new Error("device rejected command: " + (reply.error !== undefined ? String(reply.error) : "ok:false"));
  }
  if (reply.accepted === undefined || reply.accepted === null) throw new Error("reply missing accepted field");
  if (reply.limited !== undefined && typeof reply.limited !== "boolean") throw new Error("limited must be boolean");
  var limited = reply.limited === true;
  var acc = reply.accepted;
  if (Array.isArray(acc)) {
    if (acc.length !== 2) throw new Error("accepted step must have 2 values");
    var x = Number(acc[0]);
    var y = Number(acc[1]);
    if (typeof acc[0] !== "number" || typeof acc[1] !== "number") throw new Error("accepted step values must be numbers");
    if (!isFinite(x) || !isFinite(y)) throw new Error("accepted step values must be finite");
    if (Math.abs(x) > 0.1 || Math.abs(y) > 0.1) throw new Error("accepted step out of range");
    return {applied: [x, y], limited: limited};
  }
  if (typeof acc === "object") {
    if (acc.op === "lift" && (acc.position === "up" || acc.position === "down")) {
      return {applied: {op: "lift", position: acc.position}, limited: limited};
    }
    if (acc.op === "grip" && (acc.state === "open" || acc.state === "closed")) {
      return {applied: {op: "grip", state: acc.state}, limited: limited};
    }
  }
  throw new Error("accepted reply is malformed");
}

